// Village map data (pure): world size, the start framing, the building pieces and each sign's anchor, and the empty
// building plots, all in base pixels of the artwork. The artwork is generated by tools/art (village_split.py): a
// background without buildings plus one sprite per building, placed by assets/images/village/village_layout.json, which
// is read here as the single source of the pieces. Each sign is derived from its building's box (one rule, below), so
// the layout's old `sign` fields are no longer read. If the artwork changes, re-run
// `cd tools/art && python3 build_assets.py ../..`; nothing to copy by hand.
import layoutJson from '../../../assets/images/village/village_layout.json';

/** The whole map, base px. */
export const WORLD = { w: 360, h: 560 } as const;
/**
 * The start framing (the map opens centred on it, its width filling the screen): x spans the usable buildings and their
 * signs (Woodcutting's sign to the Merchant's), y is centred on the buildings plus the signs under them (world y 181 to
 * about 460); tall enough that the width sets the start zoom
 * on every phone. The Crafting house sits on the east plot, outside it (reached by panning).
 */
export const CORE = { x: 44, y: 50, w: 248, h: 540 } as const;

export type VillageAction = 'storage' | 'merchant' | 'dungeon' | 'training' | 'woodcutting' | 'mine' | 'town_hall' | 'crafting';

export type PlotId = 'west' | 'east' | 'south_west' | 'south_east';

/** village_layout.json: world size, background file, pieces back to front (`order`) with their world-px box. */
export type VillageLayout = {
  world: { w: number; h: number; scale: number };
  background: string;
  order: string[];
  pieces: Record<string, { kind: 'building' | 'decor'; file: string; x: number; y: number; w: number; h: number; z: number }>;
};

export const LAYOUT = layoutJson as VillageLayout;

/** Sign keys = usable building piece ids (`kind: 'building'`), in the order the signs are drawn. */
const SIGN_LABELS: Record<VillageAction, string> = {
  dungeon: 'Dungeon',
  mine: 'Mine Shaft',
  merchant: 'Merchant',
  woodcutting: 'Woodcutting',
  training: 'Training',
  town_hall: 'Town Hall',
  crafting: 'Crafting',
  storage: 'Storage',
};

/** Signs on a building plot outside the core village. */
const SIGN_PLOTS: Partial<Record<VillageAction, PlotId>> = { crafting: 'east' };

/**
 * Signs scale with the map (2026-11-05): a sign is the normal-size PixelButton (44 tall, 18 pt Pixelify Sans Bold label)
 * drawn inside the map layer at this scale, so on screen it is SIGN_SCALE × zoom times its natural size, like the
 * buildings. At the start zoom on a 375 pt phone (1.5625) the label is 18 × 0.5 × 1.5625 = 14 pt.
 */
export const SIGN_SCALE = 0.5;
/** Natural height of a sign button: 38 inner + 3 frame each side (PixelButton). */
export const SIGN_BUTTON_H = 44;
/** Natural label size of a sign (PixelButton `sign`). */
export const SIGN_LABEL_PT = 18;
/** Extra touch area around a sign, in natural px (scaled with it): 44 + 2 × 10 = 64 natural = 50 pt at the start zoom on 375 pt. */
export const SIGN_HIT_SLOP = 10;
/** A sign's top edge sits this far below its building box's bottom edge, world px. */
export const SIGN_GAP = 15;

/**
 * The only exceptions to the rule, world px, listed in the PR: Woodcutting's sign (padlocked, the widest) would overlap
 * the Town Hall's by 12 px, so Woodcutting's moves 7 px left and the Town Hall's 7 px right (both still under their
 * building's box, 2 px clear of each other).
 */
export const SIGN_NUDGE: Partial<Record<VillageAction, { x: number }>> = { woodcutting: { x: -7 }, town_hall: { x: 7 } };

/** A sign's anchor, world px: `x` = the horizontal centre (the building box's centre), `y` = the TOP edge. */
export function signAnchor(key: VillageAction, piece: { x: number; y: number; w: number; h: number }): { x: number; y: number } {
  return { x: piece.x + piece.w / 2 + (SIGN_NUDGE[key]?.x ?? 0), y: piece.y + piece.h + SIGN_GAP };
}

/** A sign's box in the world for a button of this natural width (label + chrome); the badge hangs below it. */
export function signWorldBox(sign: { x: number; y: number }, naturalWidth: number) {
  const w = naturalWidth * SIGN_SCALE;
  return { x0: sign.x - w / 2, x1: sign.x + w / 2, y0: sign.y, y1: sign.y + SIGN_BUTTON_H * SIGN_SCALE };
}

/** Each sign: centred under its building, top 15 world px below the building's bottom (`signAnchor`). Text only. */
export const SIGNS: readonly { key: VillageAction; label: string; x: number; y: number; plot?: PlotId }[] = (Object.keys(SIGN_LABELS) as VillageAction[]).map((key) => {
  const piece = LAYOUT.pieces[key];
  if (!piece) throw new Error(`village_layout.json has no building for ${key}`);
  const { x, y } = signAnchor(key, piece);
  return { key, label: SIGN_LABELS[key], x, y, ...(SIGN_PLOTS[key] ? { plot: SIGN_PLOTS[key] } : {}) };
});

/** One building sprite on the map, world px (the file is x4). `sign` = the sign it belongs to (decor has none). */
export type VillagePiece = { id: string; sign: VillageAction | null; x: number; y: number; w: number; h: number };

/** Every piece in draw order (back to front: the order matters, pieces overlap slightly). */
export const PIECES: readonly VillagePiece[] = LAYOUT.order.map((id) => {
  const p = LAYOUT.pieces[id];
  return { id, sign: p.kind === 'building' && id in SIGN_LABELS ? (id as VillageAction) : null, x: p.x, y: p.y, w: p.w, h: p.h };
});

/** Building plots (x0, y0, x1, y1 world px) outside the core. `east` holds the Crafting house (1.13.0); the rest are empty. */
export const PLOTS: Record<PlotId, readonly [number, number, number, number]> = {
  west: [18, 292, 62, 318],
  east: [292, 314, 336, 340],
  south_west: [106, 496, 148, 528],
  south_east: [214, 496, 256, 528],
};

/** Max zoom = this × the starting zoom (the core filling the screen). */
export const MAX_ZOOM_FACTOR = 2.5;
/**
 * Min zoom = the larger of "the map still covers the screen" and this × the starting zoom. Signs shrink with the map
 * now (so they never pile up); the limit keeps the labels readable (14 pt at start, about 10 pt at the farthest zoom out).
 */
export const MIN_ZOOM_FACTOR = 0.7;

export type MapViewport = { w: number; h: number };
export type MapCamera = { zoom: number; tx: number; ty: number };

/** Zoom limits and the start camera for a viewport (points per world px; tx/ty = screen position of world 0,0). */
export function mapLimits(view: MapViewport, top = 0, bottom = 0) {
  const cover = Math.max(view.w / WORLD.w, view.h / WORLD.h);
  const start = Math.max(cover, view.w / CORE.w, view.h / CORE.h);
  const minZoom = Math.max(cover, start * MIN_ZOOM_FACTOR);
  const maxZoom = start * MAX_ZOOM_FACTOR;
  // Centre the core in the band the HUD and the activity strip leave visible.
  const cx = CORE.x + CORE.w / 2;
  const cy = CORE.y + CORE.h / 2;
  const bandMid = top + (view.h - top - bottom) / 2;
  const camera = clampCamera({ zoom: start, tx: view.w / 2 - cx * start, ty: bandMid - cy * start }, view);
  return { minZoom, maxZoom, start, camera };
}

/** Keeps the map covering the screen: no empty bars on any side. */
export function clampCamera(c: MapCamera, view: MapViewport): MapCamera {
  'worklet';
  const minX = view.w - WORLD.w * c.zoom;
  const minY = view.h - WORLD.h * c.zoom;
  return { zoom: c.zoom, tx: Math.min(0, Math.max(minX, c.tx)), ty: Math.min(0, Math.max(minY, c.ty)) };
}
